  chips=[('“Not cool.”', '“Eso no está bien.”'), ('“I don’t play like that.”', '“Yo no juego así.”'), ('“I need you to stop.”', '“Necesito que pares.”'), ('“Let’s talk later.”', '“Hablemos después.”'), ('“I’m good. I’m out.”', '“Estoy bien. Me voy.”')],
